const outline = context.outline.response;
const lines = outline.split('\n').filter(line => line.trim());
const points = lines.map((line, index) => ({
  number: index + 1,
  text: line.replace(/^\d+\.|\*|-/g, '').trim()
}));
return { processed: true, points, originalLength: lines.length };
